function updateProfileModalUI() {
  const role = appAuth.getCurrentFarmRole(); // 'owner' | 'partner' | null
  const $partner = document.getElementById('teamPartnerSection');
  const $join    = document.getElementById('teamJoinContainer');

  if (role === 'partner') {
